INSERT INTO `information` (`id`, `title`, `slug`, `summary`, `content`, `category`, `source_name`, `image_path`, `source_url`, `is_published`, `published_at`, `views`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 'Navigasi Rasa: Panduan Lengkap Mengenal Karakteristik Arabica, Robusta, Liberica, dan Excelsa', 'navigasi-rasa-panduan-lengkap-mengenal-karakteristik-arabica-robusta-liberica-dan-excelsa', 'Kenali perbedaan mendasar antara empat jenis kopi utama yang mendominasi industri global. Dari kompleksitas rasa Arabica hingga aroma unik Liberica, pahami karakteristik setiap biji untuk meningkatkan standar seduhan dan bisnis kopi Anda.', '\r\n                    <p>Pemahaman mengenai varietas tanaman kopi adalah fondasi utama bagi siapa pun yang ingin menyelami dunia kopi lebih dalam, baik sebagai penikmat maupun pelaku usaha. Rasa yang muncul di dalam cangkir bukanlah sebuah kebetulan, melainkan jejak genetika dan pengaruh lingkungan tempat pohon tersebut tumbuh. Di Indonesia, kita memiliki akses yang luar biasa terhadap berbagai jenis kopi. Berikut adalah ulasan mendalam mengenai empat jenis kopi utama yang mendefinisikan standar industri saat ini:</p>\r\n\r\n<p><strong>1. Kopi Arabica: Kompleksitas di Dataran Tinggi</strong> Arabica merupakan spesies yang paling dihargai dalam pasar <em>specialty coffee</em>. Tanaman ini tumbuh optimal di dataran tinggi, biasanya di atas 1.000 mdpl. Proses pematangan yang lambat di suhu sejuk menciptakan kepadatan biji yang menghasilkan spektrum rasa yang sangat luas. Karakter utamanya adalah tingkat keasaman (<em>acidity</em>) yang cerah, aroma bunga, dan catatan rasa buah-buahan. Arabica memiliki kadar gula yang tinggi namun kafein yang rendah (1.2% - 1.5%).</p>\r\n\r\n<p><strong>2. Kopi Robusta: Pilar Kekuatan dan Ketangguhan</strong> Sesuai namanya, Robusta dikenal karena daya tahannya yang luar biasa terhadap hama dan suhu panas. Tumbuh di dataran rendah (di bawah 800 mdpl), spesies ini menjadi tulang punggung industri kopi komersial. Robusta tidak mengejar keasaman, melainkan menonjolkan <em>body</em> yang tebal dan rasa pahit yang tegas dengan aroma kacang-kacangan atau cokelat gelap. Kadar kafeinnya mencapai 2.2% - 2.7%, menjadikannya pilihan utama untuk campuran espresso dan kopi susu.</p>\r\n\r\n<p><strong>3. Kopi Liberica: Warisan Eksotis yang Unik</strong> Liberica memiliki karakteristik fisik yang sangat mencolok dengan ukuran pohon mencapai 20 meter dan biji yang paling besar. Di Indonesia, ia sering disebut sebagai \"Kopi Nangka\" karena aromanya yang sangat tajam menyerupai buah nangka matang. Profil rasanya sangat unik, memadukan kepahitan yang pekat dengan sensasi <em>smoky</em> (asap) dan aroma kayu yang tidak ditemukan pada spesies lain.</p>\r\n\r\n<p><strong>4. Kopi Excelsa: Dimensi Rasa yang Tersembunyi</strong> Walaupun secara teknis merupakan bagian dari keluarga Liberica, Excelsa memiliki kepribadian rasa yang kontras. Ia menawarkan kedalaman rasa yang kuat (<em>bold</em>) khas kopi dataran rendah, namun disertai dengan tingkat keasaman buah yang tajam mirip ceri atau beri. Karena aromanya yang kuat, Excelsa sering dimanfaatkan sebagai \"komponen rahasia\" dalam racikan <em>house blend</em> untuk menambah kompleksitas aroma.<a href=\"/storage/imports/public/5dc9addba775049723b5de7d24f1888e208c37aef647f347000929ffd172b79a.png\"><img src=\"/storage/imports/public/5dc9addba775049723b5de7d24f1888e208c37aef647f347000929ffd172b79a.png\" width=\"1078\" height=\"540\" alt=\"lDIJgwExFAFAGWbLfoXQ7LXkomfOKvsngSkQjygh.png\">Jenis Jenis Kopi</a></p>\r\n                ', 'Edukasi', 'Tim WadahNgopi', 'imports/public/de88d10346d3795b0d40f3932a96278f0b7e95a964394cc189bb2383e9652303.png', 'https://wadahngopi.com/information/navigasi-rasa-panduan-lengkap-mengenal-karakteristik-arabica-robusta-liberica-dan-excelsa', 1, '2026-02-21 16:00:00', 109, '2026-10-27 05:52:01', '2026-10-29 16:50:04', NULL),
(2, 'Paket Bukber Widi Coffee: Menu Spesial Ramadhan Mulai 65K, Lengkap dengan Takjil Unik!', 'paket-bukber-widi-coffee-menu-spesial-ramadhan-mulai-65k-lengkap-dengan-takjil-unik', 'Rasakan kehangatan buka puasa dengan menu khas Nusantara di Widi Coffee. Tersedia paket personal hingga paket ramesan untuk 6 orang mulai dari 350K. Lengkap dengan takjil Kurma Peanut Butter!', '\r\n                    <p>Buka puasa bukan cuma soal makan, tapi soal cerita, tawa, dan kebersamaan. Tahun ini, <strong>Widi Coffee</strong> menghadirkan pengalaman bukber yang berbeda dengan sentuhan rasa rumahan yang autentik dan suasana kedai yang nyaman.</p>\r\n\r\n<p>Kami menyediakan pilihan paket yang cocok untuk Anda yang datang sendiri maupun rombongan:</p>\r\n\r\n<p><strong>1. Paket Bukber Personal (65K)</strong> Solusi praktis buat yang mau bukber sendiri atau berdua tapi tetap spesial:</p>\r\n\r\n<ul><li>Ayam Bakar / Patin Bakar</li><li>Serondeng Jagung &amp; Mandai Goreng</li><li>Sambal Belimbing / Hampalam</li><li><strong>FREE:</strong> Kurma Peanut Butter &amp; Es Teh</li></ul>\r\n\r\n<p><strong>2. Paket Bukber Rame-Rame - 6 Orang (350K)</strong> Pilihan terbaik untuk kebersamaan keluarga atau teman kantor:</p>\r\n\r\n<ul><li>Ayam Bakar &amp; Patin Bakar</li><li>Serondeng Jagung &amp; Mandai Goreng</li><li>Ikan Asin &amp; Gangan Asam</li><li>Sambal Belimbing / Hampalam</li><li>Nasi Sebakul</li><li><strong>FREE:</strong> Kurma Peanut Butter &amp; Es Teh</li></ul>\r\n\r\n<p>Nikmati perpaduan rasa pedas-asam segar khas daerah yang bikin momen bukber jadi lebih berkesan hanya di Widi Coffee.</p>\r\n\r\n<p><strong>Lokasi &amp; Reservasi</strong> </p>\r\n\r\n<p><strong>Instagram:</strong> @widicoffee</p>\r\n\r\n<p><a href=\"/storage/imports/public/4aacc331478f9016e9a183e8aec7db75817ff581fb4e2dab2e6686a99a12ab5f.jpg\"><img src=\"/storage/imports/public/4aacc331478f9016e9a183e8aec7db75817ff581fb4e2dab2e6686a99a12ab5f.jpg\" width=\"1080\" height=\"1350\" alt=\"tMzqeehx8Ej94lTbnjwm9YqD3FFQrapSZkLVGtfY.jpg\">Promo</a></p>\r\n                ', 'Promo', 'Tim WadahNgopi', 'imports/public/0ded38b5e1be6731efe4be602e0ec4e1af203bd7d9ec3e312424484649f83408.jpg', 'https://wadahngopi.com/information/paket-bukber-widi-coffee-menu-spesial-ramadhan-mulai-65k-lengkap-dengan-takjil-unik', 1, '2026-02-21 16:00:00', 95, '2026-10-27 05:52:01', '2026-10-27 07:49:47', NULL),
(3, 'Bukber Hemat di Raya\'s Caffe: Nikmati Spesialis Nasi Tutug Oncom Mulai 25 Ribu!', 'paket-bukber-rayas-caffe-samarinda-tutug-oncom', 'Cari menu bukber yang beda? Raya\'s Caffe hadir dengan Paket Bukber Ramadan Penuh Berkah. Ada Nasi Tutug Oncom, Nasi Campur, hingga Bowl Beef mulai 25K, sudah dapat Es Teh Manis dan Takjil!', '\r\n                    <p>Ramadan Penuh Berkah di <strong>Raya\'s Caffe</strong>! 🌙✨</p>\r\n\r\n<p>Buat kamu yang rindu masakan Nusantara yang otentik untuk berbuka puasa, Raya\'s Caffe telah menyiapkan berbagai pilihan paket kenyang dengan harga yang sangat bersahabat. Spesialisasi kami, <strong>Nasi Tutug Oncom</strong>, siap memanjakan lidah kamu!</p>\r\n\r\n<p><strong>Daftar Paket Bukber Raya\'s Caffe:</strong></p>\r\n\r\n<ul><li><strong>Paket Nasi Campur (25K):</strong> Nasi + Ayam + Lauk Pendamping + Es Teh Manis + Takjil.</li><li><strong>Paket Nasi Tutug Oncom (30K):</strong> Nasi Tutug Oncom Spesial + Ayam + Es Teh Manis + Takjil.</li><li><strong>Paket Nasi Tutug Oncom Komplit (40K):</strong> Porsi lebih lengkap dengan tambahan lauk + Es Teh Manis + Takjil.</li><li><strong>Paket Bowl Beef (80K):</strong> Beef Bowl Series + Es Teh Manis + Takjil.</li><li><strong>Paket Rame-Rame (140K):</strong> Paket porsi besar untuk keluarga atau teman-teman.</li></ul>\r\n\r\n<p>Semua paket sudah termasuk <strong>FREE Takjil</strong> dan <strong>Es Teh Manis Segar</strong>. Cocok banget buat kamu yang ingin buka puasa dengan rasa yang \"rumahan\" banget tapi di tempat yang nyaman.</p>\r\n\r\n<p><strong>Lokasi &amp; Informasi:</strong></p>\r\n\r\n<ul><li><strong>Alamat:</strong> Jl. KS Tubun Dalam, Dadi Mulya, Kec. Samarinda Ulu, Kota Samarinda.</li><li><strong>Instagram:</strong> @rayas_caffe_smd<a href=\"/storage/imports/public/ec6babe5a463ce9fa6289354260a91f30e5521c3e05e55e945d8da1cca53f9d8.webp\"><img src=\"/storage/imports/public/ec6babe5a463ce9fa6289354260a91f30e5521c3e05e55e945d8da1cca53f9d8.webp\" width=\"1080\" height=\"1350\" alt=\"Lluj6swctdxpqIORDIuKx45BczoJiVuBWsp4KlIQ.webp\">Promo</a></li></ul>\r\n\r\n<div><a href=\"/storage/imports/public/092059c71b4816af9f33edc6485562ebbb9b1b7a76a49e304ac7c0576cc0a6ac.webp\"><img src=\"/storage/imports/public/092059c71b4816af9f33edc6485562ebbb9b1b7a76a49e304ac7c0576cc0a6ac.webp\" width=\"1080\" height=\"1350\" alt=\"crSF8DbxRV0HBsl4PRIwOjAb9h2eXcnPcaTAjtWd.webp\">Promo</a><a href=\"/storage/imports/public/fd4342f1cd79227688c23aefddc2f4b3f7ef62a391efdc213b47822b4cfbb727.webp\"><img src=\"/storage/imports/public/fd4342f1cd79227688c23aefddc2f4b3f7ef62a391efdc213b47822b4cfbb727.webp\" width=\"1080\" height=\"1350\" alt=\"fLaGqBDnsIynniujy5HuMtckTVE5jtlhTDEgt8Et.webp\">Promo</a><a href=\"/storage/imports/public/99ff93b8b2c4813e02317823a8694af32aae99695ac4e64de6c020e409aef33c.webp\"><img src=\"/storage/imports/public/99ff93b8b2c4813e02317823a8694af32aae99695ac4e64de6c020e409aef33c.webp\" width=\"1080\" height=\"1350\" alt=\"viQ0wvjul451U2g7M5PEb8785LhAGNOm36A3rnV2.webp\">Promo</a><a href=\"/storage/imports/public/ab5bf2ffc996f69b19ab0c39d17d7ee1d31c4ffc33d949077b6893e6d9ddb80d.webp\"><img src=\"/storage/imports/public/ab5bf2ffc996f69b19ab0c39d17d7ee1d31c4ffc33d949077b6893e6d9ddb80d.webp\" width=\"1080\" height=\"1350\" alt=\"tWg1cr4SKwaCJc43JBxquFniNcznazJoClhCbR8v.webp\">Promo</a></div>\r\n\r\n<div><a href=\"/storage/imports/public/3dfea754cc4d35d6724e626894c4feb816f7d9225a57048c2e4ab85466809895.webp\"><img src=\"/storage/imports/public/3dfea754cc4d35d6724e626894c4feb816f7d9225a57048c2e4ab85466809895.webp\" width=\"1080\" height=\"1350\" alt=\"fTdoiaSiSWVkFHZb8ShmdkKfkg3HSrvx4mPzbaod.webp\">Promo</a><a href=\"/storage/imports/public/001bb4fc8e48a435284a73388a4daa1a8f4beaefdcbf189b841c5957725d9ff1.webp\"><img src=\"/storage/imports/public/001bb4fc8e48a435284a73388a4daa1a8f4beaefdcbf189b841c5957725d9ff1.webp\" width=\"1080\" height=\"1350\" alt=\"P3etY2wDp3SBdCAVamQDj6SUpQbrlbBLrMYI2dlo.webp\">Promo</a></div>\r\n                ', 'Promo', 'Tim WadahNgopi', 'imports/public/56a1c27572cae84b143d35fa089940ae58946423fe30cd959670a4ecd0119d84.jpg', 'https://wadahngopi.com/information/paket-bukber-rayas-caffe-samarinda-tutug-oncom', 1, '2026-02-22 16:00:00', 50, '2026-10-27 05:52:01', '2026-10-29 16:50:05', NULL),
(4, 'Paket Iftar Kopi Loa Indonesia: Buka Puasa Kenyang & Hemat Mulai 25 Ribu!', 'paket-iftar-ramadan-kopi-loa-samarinda', 'Sambut keberkahan Ramadan 1447 H bersama Kopi Loa Indonesia! Nikmati 6 pilihan paket iftar mulai dari 25K yang sudah termasuk Lemon Tea dan takjil gratis. Cek detail menunya di sini!', '\r\n                    <p>Marhaban ya Ramadhan 1447 H! 🌟</p>\r\n\r\n<p>Buka puasa makin spesial dengan <strong>Paket Iftar Ramadan dari Kopi Loa Indonesia</strong>. Menu lengkap, harga bersahabat, dan rasa yang bikin rindu siap menemani momen kebersamaan Anda di bulan suci ini.</p>\r\n\r\n<p>Berikut pilihan paket yang bisa Anda nikmati:</p>\r\n\r\n<ul><li><strong>Paket 1 (Rp 28.000)</strong>: Spaghetti Carbonara + FREE Lemon Tea &amp; Takjil.</li><li><strong>Paket 2 (Rp 28.000)</strong>: Spaghetti Bolognese + FREE Lemon Tea &amp; Takjil.</li><li><strong>Paket 3 (Rp 25.000)</strong>: Nasi Telor Pontianak + FREE Lemon Tea &amp; Takjil.</li><li><strong>Paket 4 (Rp 28.000)</strong>: Rice Bowl Chicken Katsu (Teriyaki/Blackpepper/Hot Lava) + FREE Lemon Tea &amp; Takjil.</li><li><strong>Paket 5 (Rp 33.000)</strong>: Rice Bowl Belly (Teriyaki/Blackpepper/Hot Lava) + FREE Lemon Tea &amp; Takjil.</li><li><strong>Paket 6 (Rp 28.000)</strong>: Honey Chicken Karage + FREE Lemon Tea &amp; Takjil.</li></ul>\r\n\r\n<p>Semoga Ramadhan ini membawa kedamaian, kelancaran dalam beraktivitas, serta meningkatkan ketakwaan dan kebersamaan kita semua.</p>\r\n\r\n<p><strong>Lokasi &amp; Reservasi</strong>:</p>\r\n\r\n<ul><li><strong>Alamat</strong>: Jl. Anggur Dalam Ruko No. 12 (Deretan Indomaret), Samarinda.</li><li><strong>WhatsApp</strong>: 0819-9888-7771</li><li><strong>Instagram</strong>: @kopiloaindonesia<a href=\"/storage/imports/public/54c55b7143293d7458e7467049e4c630c5addf84e0623521df0df20b2d1e2232.jpg\"><img src=\"/storage/imports/public/54c55b7143293d7458e7467049e4c630c5addf84e0623521df0df20b2d1e2232.jpg\" width=\"1080\" height=\"1440\" alt=\"IL5P62I0KTerWS0hKLl6Pp0rxoDnqPde0TnMCmWt.jpg\">Promo</a></li></ul>\r\n                ', 'Promo', 'Tim WadahNgopi', 'imports/public/d95403d5ca95050ab13bfc098d670c9365864632b1dbffc0df7c36098723a7be.jpg', 'https://wadahngopi.com/information/paket-iftar-ramadan-kopi-loa-samarinda', 1, '2026-02-22 16:00:00', 46, '2026-10-27 05:52:01', '2026-10-27 07:49:47', NULL),
(5, 'Pantun Bukber ala Galuh Coffee: Yuk, Buka Puasa Bersama di Sini!', 'ajakan-bukber-galuh-coffee-samarinda', 'Galuh Coffee punya cara unik buat ngajak kamu bukber! Lewat pantun spesial, mereka mengundang Sobat Ngopi untuk merayakan momen kebersamaan di bulan Ramadan. Cek infonya di sini!', '\r\n                    <p><em>Minum kopi sambil baca koran,</em> <em>Lihat kakak di kebun memberantas hama.</em> <em>Dari aku pribadi ingin menyampaikan,</em> <em>Yuk kita berbuka puasa bersama!</em></p>\r\n\r\n<p>Bulan Ramadan selalu punya cerita, dan <strong>Galuh Coffee</strong> ingin menjadi bagian dari cerita buka puasa Anda tahun ini. Bukan sekadar tempat ngopi, Galuh Coffee menawarkan suasana yang hangat dan akrab, sangat cocok untuk Anda yang ingin melepas dahaga sambil bercerita selepas seharian berpuasa.</p>\r\n\r\n<p>Berikut adalah <strong>Pilihan Paket Bukber Galuh Coffee</strong> yang bisa Anda pilih:</p>\r\n\r\n<ul><li><strong>BUKBER 1 (35K):</strong> Nasi Rendang, Tempe Teri, Acar Nanas, Kerupuk, dan Sambal Merah.</li><li><strong>BUKBER 2 (35K):</strong> Ikan Mas, Nasi Putih, Kuah Sop, Tempe Tahu, Kerupuk, dan Sambal Ijo.</li><li><strong>BUKBER 3 (35K):</strong> Ayam Rica, Nasi Putih, Mie Goreng, Acar, dan Kerupuk.</li><li><strong>BUKBER 4 (35K):</strong> Ikan Tuna Bumbu, Nasi Putih, Mie Goreng, Acar, dan Kerupuk.</li><li><strong>BUKBER 5 (35K):</strong> Ikan Nila Goreng, Nasi Putih, Tahu Tempe, Kuah Sop/Soto, Kerupuk, dan Sambal Ijo.</li><li><strong>BUKBER 6 (30K):</strong> Ayam Lalapan, Nasi Putih, Tahu Tempe, Kuah Sop/Soto, Kerupuk, dan Sambal Ijo.</li><li><strong>BUKBER 7 (25K):</strong> Soto Ibu Mertua, Nasi Putih, dan Kerupuk.</li></ul>\r\n\r\n<p><strong>Catatan:</strong> Semua paket di atas sudah termasuk <strong>Air Mineral dan Takjil</strong>.</p>\r\n\r\n<p><strong>Kenapa Harus Bukber di Galuh Coffee?</strong></p>\r\n\r\n<ul><li><strong>Suasana Tenang:</strong> Cocok untuk yang mencari tempat bukber yang tidak terlalu bising sehingga obrolan lebih berkualitas.</li><li><strong>Menu Ekonomis:</strong> Pilihan paket lengkap dengan harga sangat bersahabat, mulai dari 25 ribu rupiah saja.</li><li><strong>Pelayanan Ramah:</strong> Berasa buka puasa di rumah sendiri!</li></ul>\r\n\r\n<p>Jangan biarkan rencana bukbermu sekadar wacana. Mari rapatkan barisan, atur jadwal, dan langsung meluncur ke Galuh Coffee. Kami siap menyambut kehadiran Anda dan orang-orang tersayang.</p>\r\n\r\n<p><strong>Lokasi &amp; Informasi:</strong></p>\r\n\r\n<ul><li><strong>Instagram:</strong> @galuh_coffee</li></ul>\r\n\r\n<p><a href=\"/storage/imports/public/6205bd5a0d00b18cd0cbd6917f14c4954897fccb5cbe4a4181313491e0ad96e3.jpg\"><img src=\"/storage/imports/public/6205bd5a0d00b18cd0cbd6917f14c4954897fccb5cbe4a4181313491e0ad96e3.jpg\" width=\"1080\" height=\"1348\" alt=\"kkZv4wrS4wenfde7OtQMY21JDtxn3FXPLW7ElPas.jpg\"></a><a href=\"/storage/imports/public/6205bd5a0d00b18cd0cbd6917f14c4954897fccb5cbe4a4181313491e0ad96e3.jpg\"><span style=\"text-decoration:underline;\">Promo</span></a></p>\r\n                ', 'Promo', 'Tim WadahNgopi', 'imports/public/11a0bbe12d9641f491836a736c79ec6f6e67eaa133d406d4aa779ad4b9d05780.jpg', 'https://wadahngopi.com/information/ajakan-bukber-galuh-coffee-samarinda%20%20Category:%20Promo', 1, '2026-02-22 16:00:00', 40, '2026-10-27 05:52:02', '2026-10-27 07:49:47', NULL),
(6, 'Bukber Bukan Cuma Soal Makan: Promo Paket Nusantara Giras Mulai 120K untuk Berdua!', 'promo-paket-bukber-giras-kitchen-coffee-samarinda', 'Ajak mereka yang biasanya cuma ada di chat buat ketemu langsung di Giras Kitchen & Coffee! Nikmati paket bukber Nusantara & Rice Bowl mulai 120K per 2 orang, lengkap dengan free takjil.', '\r\n                    <p>Bukber nggak cuma soal makan, tapi soal siapa yang duduk satu meja bareng kamu. <strong>Giras Kitchen &amp; Coffee</strong> mengundang Anda untuk mengubah obrolan di <em>chat</em> menjadi momen temu kangen yang nyata di meja makan.</p>\r\n\r\n<p>Tahun ini, Giras menghadirkan pilihan menu yang variatif, mulai dari citarasa Nusantara yang otentik hingga praktisnya <em>Rice Bowl</em> kekinian.</p>\r\n\r\n<p><strong>Detail Promo Bukber Giras:</strong></p>\r\n\r\n<ul><li><strong>Harga Paket:</strong> Mulai dari <strong>Rp 120.000 untuk 2 orang (2 pax)</strong>.</li><li><strong>Pilihan Menu:</strong> Tersedia aneka menu Nusantara dan <em>Rice Bowl</em>.</li><li><strong>Benefit Tambahan:</strong> <strong>FREE Takjil</strong> untuk setiap pemesanan paket bukber.</li></ul>\r\n\r\n<p>Suasana Giras yang nyaman sangat cocok untuk Anda yang ingin mengobrol santai lebih lama setelah berbuka. Pastikan Anda melakukan reservasi terlebih dahulu karena slot harian terbatas!</p>\r\n\r\n<p><strong>Lokasi &amp; Reservasi:</strong></p>\r\n\r\n<ul><li><strong>WhatsApp Reservasi:</strong> 0851-2423-1809</li><li><strong>Instagram:</strong> @giras.smr</li></ul>\r\n\r\n<div><a href=\"/storage/imports/public/1c525a9e0a9d2fdbee019ea4e3f38fdc9a9143b7105568ce93f1e84998ce65cd.jpg\"><img src=\"/storage/imports/public/1c525a9e0a9d2fdbee019ea4e3f38fdc9a9143b7105568ce93f1e84998ce65cd.jpg\" width=\"1080\" height=\"1350\" alt=\"YAPgQPnDMYqE7zJZDg6uBTIvxs7OAbijYpJXuF0w.jpg\">Promo</a><a href=\"/storage/imports/public/2a3860e60ae94084f2c6ee702bf979a093dff586cb8182b31181e4e6cbde7e9e.jpg\"><img src=\"/storage/imports/public/2a3860e60ae94084f2c6ee702bf979a093dff586cb8182b31181e4e6cbde7e9e.jpg\" width=\"1080\" height=\"1350\" alt=\"PqQVjZTXTSgbQ5HaCr8O15Ctrl71s3UZLL013Buu.jpg\">Promo</a></div>\r\n                ', 'Promo', 'Tim WadahNgopi', 'imports/public/c495ad4e2183e89e43453e10cfbfbf1cc9fe1e7b865b33dea4c21930bcf7780f.jpg', 'https://wadahngopi.com/information/promo-paket-bukber-giras-kitchen-coffee-samarinda', 1, '2026-02-22 16:00:00', 34, '2026-10-27 05:52:02', '2026-10-27 07:49:47', NULL),
(7, 'Bukber di Sela Coffee & Tea: Beli Menu Favorit, Gratis Takjil Kurma & Es Teh!', 'promo-ramadhan-free-takjil-sela-coffee-tea-samarinda', 'Nikmati promo spesial Ramadan di Sela Coffee & Tea! Setiap pembelian menu favorit untuk berbuka puasa, kamu langsung dapat FREE takjil berupa kurma dan es teh segar.', '\r\n                    <p>Marhaban Ya Ramadhan! 🌙✨</p>\r\n\r\n<p>Momen buka puasa jadi lebih manis di <strong>Sela Coffee &amp; Tea</strong>. Selama bulan suci ini, ada <strong>Promo Spesial Ramadan</strong> buat kamu yang ingin reservasi bukber bareng teman atau keluarga.</p>\r\n\r\n<p><strong>Detail Promo:</strong></p>\r\n\r\n<ul><li><strong>FREE Takjil</strong>: Dapatkan gratis Kurma dan Es Teh untuk setiap pembelian menu favorit kamu.</li><li><strong>Syarat &amp; Ketentuan</strong>: Berlaku selama bulan Ramadan.</li></ul>\r\n\r\n<p>Yuk, amankan meja kamu dan reservasi sekarang juga agar momen berbuka tetap nyaman!</p>\r\n\r\n<p><strong>Informasi &amp; Reservasi:</strong></p>\r\n\r\n<ul><li><strong>Instagram</strong>: @sela.coffeeandtea<a href=\"/storage/imports/public/2f71993a76b5e71f3bb66cf6eb141610442d4fdbf4589e4ae6a2758da7f7915d.jpg\"><img src=\"/storage/imports/public/2f71993a76b5e71f3bb66cf6eb141610442d4fdbf4589e4ae6a2758da7f7915d.jpg\" width=\"1080\" height=\"1349\" alt=\"smPOUEnbJDGO29gpe9wUt53K381DceaJBHgDtxDN.jpg\"><span>SaveClip.App_637722162_17849354172683475_4800576146077368714_n.jpg</span> <span>155.46 KB</span></a></li></ul>\r\n                ', 'Promo', 'Tim WadahNgopi', 'imports/public/bf972af28572ac52b198e422d3b5fde092179f517ff721f52c1ac2295595eb36.jpg', 'https://wadahngopi.com/information/promo-ramadhan-free-takjil-sela-coffee-tea-samarinda', 1, '2026-02-22 16:00:00', 25, '2026-10-27 05:52:02', '2026-10-27 07:49:47', NULL),
(8, 'Ramadan Delight di Double Dose: Paket Bundling Iftar Premium Mulai 55K!', 'ramadan-delight-bundling-package-double-dose-samarinda', 'Buka puasa lebih berkesan di Double Dose (DD)! Nikmati promo \"Ramadan Delight Bundling Package\" dengan pilihan menu Spaghetti hingga Japanese Chicken Curry mulai dari 55K saja.', '\r\n                    <p><em>Ramadan is better with good food &amp; great company!</em> 🤍</p>\r\n\r\n<p><strong>Double Dose</strong> menghadirkan <strong>Ramadan Delight Bundling Package</strong> yang dirancang khusus untuk momen iftar Anda bersama teman dan keluarga tercinta. Cukup dengan <strong>Rp 55.000 per bundle</strong>, Anda sudah bisa menikmati kombinasi menu utama dan minuman segar pilihan.</p>\r\n\r\n<p><strong>Pilihan Menu Utama (Main Course):</strong></p>\r\n\r\n<ul><li><strong>Spaghetti Series</strong>: <em>ala Stoganoff</em>, <em>Bologna</em>, atau <em>Aglio e Porro</em>.</li><li><strong>Rice Series</strong>: <em>Chicken Karage Colo-Colo</em>, <em>Japanese Chicken Curry</em>, <em>Chicken Blackpepper</em>, atau <em>Spicy Salted Chicken</em>.</li></ul>\r\n\r\n<p><strong>Pilihan Minuman (Beverages):</strong></p>\r\n\r\n<ul><li>Tea (Varian: <em>Peach, Mango, Apple, Passion Fruit, Elder Flower</em>).</li></ul>\r\n\r\n<p>Promo ini tersedia khusus untuk layanan <strong>Dine-in</strong>. Segera tentukan pilihan menu favoritmu dan nikmati suasana bukber yang hangat di DD!</p>\r\n\r\n<p><strong>Lokasi &amp; Reservasi:</strong></p>\r\n\r\n<ul><li><strong>Alamat</strong>: Jl. Wijaya Kusuma, Samarinda.</li><li><strong>Instagram</strong>: @doubledose.og</li></ul>\r\n\r\n<p><a href=\"/storage/imports/public/94beee6ab0ca502d86f2d5bad8c2abb74a12982590278222f678e7f9238400ca.jpg\"><img src=\"/storage/imports/public/94beee6ab0ca502d86f2d5bad8c2abb74a12982590278222f678e7f9238400ca.jpg\" width=\"1080\" height=\"1350\" alt=\"6cKcvGuspjJYBWmX6N1oA3i0XuDjiW321M0BKnlQ.jpg\"></a><a href=\"/storage/imports/public/94beee6ab0ca502d86f2d5bad8c2abb74a12982590278222f678e7f9238400ca.jpg\"><span style=\"text-decoration:underline;\">Promo</span></a><a href=\"/storage/imports/public/2c61c70821b1f14f531231fa3a0980d22fafb58e76180b52ceab1d8370d19296.jpg\"><img src=\"/storage/imports/public/2c61c70821b1f14f531231fa3a0980d22fafb58e76180b52ceab1d8370d19296.jpg\" width=\"1080\" height=\"1350\" alt=\"8KIkYxB0B30IZEQcxbSdtRkNOPZrIm9S5ndQhjqJ.jpg\"></a><a href=\"/storage/imports/public/2c61c70821b1f14f531231fa3a0980d22fafb58e76180b52ceab1d8370d19296.jpg\"><span style=\"text-decoration:underline;\">Promo</span></a></p>\r\n                ', 'Promo', 'Tim WadahNgopi', 'imports/public/f94ba7f99a21eb51016ca4b074cd2cbad29c7f1be494c3d0429b2b67b41e0826.jpg', 'https://wadahngopi.com/information/ramadan-delight-bundling-package-double-dose-samarinda', 1, '2026-02-22 16:00:00', 28, '2026-10-27 05:52:02', '2026-10-27 07:49:47', NULL),
(9, 'Vlorry Iftar Time: Nikmati Kehangatan Ramadan dengan Paket Lengkap Mulai 57K!', 'vlorry-ramadhan-package-samarinda', 'Buka puasa di Vlorry Coffee terasa beda! Nikmati \"Vlorry Ramadhan Package\" dengan 6 pilihan menu mulai dari Ayam Penyet sampai Katsu Curry, lengkap dengan takjil (kurma, buah, puding coklat).', '\r\n                    <p><em>Vlorry iftar time feels different!</em> 🌙✨</p>\r\n\r\n<p>Saatnya berbagi kebahagiaan di meja makan. <strong>Vlorry Coffee</strong> telah menyediakan <strong>Ramadhan Package</strong> spesial untuk menemani momen buka puasa Anda di bulan penuh berkah ini. Kami menyajikan pilihan menu Nusantara hingga <em>Western</em> yang sudah dikurasi khusus.</p>\r\n\r\n<p><strong>Pilihan Vlorry Ramadhan Package:</strong></p>\r\n\r\n<ul><li><strong>Paket A (57K):</strong> Ayam Penyet + Original Tea + Takjil.</li><li><strong>Paket B (57K):</strong> Chicken Sambal Matah + Original Tea + Takjil.</li><li><strong>Paket C (60K):</strong> Nasi Goreng Kampung + Original Tea + Takjil.</li><li><strong>Paket D (60K):</strong> Beef Teriyaki + Original Tea + Takjil.</li><li><strong>Paket E (63K):</strong> Grilled Chicken Salad + Original Tea + Takjil.</li><li><strong>Paket F (68K):</strong> Katsu Curry + Original Tea + Takjil.</li></ul>\r\n\r\n<p><strong>Catatan:</strong> Semua paket sudah termasuk <strong>Takjil Spesial</strong> berupa Kurma, Buah, dan Puding Coklat.</p>\r\n\r\n<p>Segera amankan meja Anda untuk berbuka puasa bersama teman, sahabat, atau keluarga tercinta.</p>\r\n\r\n<p><strong>Lokasi &amp; Reservasi:</strong></p>\r\n\r\n<ul><li><strong>Alamat:</strong> Jln. Anggur, Samarinda Ulu.</li><li><strong>WhatsApp:</strong> 0851-9046-9944.</li><li><strong>Instagram:</strong> @vlorry.coffee<a href=\"/storage/imports/public/85796a7eab74d15262cf827b1232fc4c0e46fbea019c488ad15d9453642d2123.jpg\"><img src=\"/storage/imports/public/85796a7eab74d15262cf827b1232fc4c0e46fbea019c488ad15d9453642d2123.jpg\" width=\"1080\" height=\"1350\" alt=\"vmz0h1FaOGWIJbn9VRZlaHaChAbUtdxCfFR7f3L7.jpg\">Promo</a></li></ul>\r\n                ', 'Promo', 'Tim WadahNgopi', 'imports/public/e4e3b5b546216ca6bd1dad7477b4f4ab0853aa3fa1c2eddcd0bd3a9ccb97043f.jpg', 'https://wadahngopi.com/information/vlorry-ramadhan-package-samarinda', 1, '2026-02-22 16:00:00', 30, '2026-10-27 05:52:03', '2026-10-27 07:49:47', NULL),
(10, 'WN x PUBG Mobile: Mabar & Bukber di Jawara Basecamp Samarinda!', 'wn-x-pubg-mobile-mabar-bukber-di-jawara-basecamp-samarinda', 'Ramaikan event PUBG Mobile di Jawara Basecamp (Wadah Nangkring)! Ada daily prize pool Rp 500.000, free takjil, hingga tournament offline dengan total hadiah jutaan rupiah.', '\r\n                    <p>Siap <em>push rank</em> sambil nunggu bedug? <strong>Wadah Nangkring (WN)</strong> resmi jadi <strong>Jawara Basecamp Samarinda</strong> untuk event spesial Ramadan diTHRaktir PUBG Mobile!</p>\r\n\r\n<p><strong>1. Mabar &amp; Bukber Jawara Basecamp</strong></p>\r\n\r\n<p>Datang dan ramaikan keseruan main bareng squad kamu setiap hari selama periode event.</p>\r\n\r\n<ul><li><strong>Periode</strong>: 23 Februari – 8 Maret 2026</li><li><strong>Waktu</strong>: 16.00 – 20.00 WITA</li><li><strong>Benefit</strong>:<ul><li><em>Daily Prize Pool</em> Rp 500.000 per hari.</li><li><strong>FREE Takjil</strong> setiap hari buat yang mabar di lokasi.</li></ul></li><li><strong>Level Mabar</strong>:<ul><li>Datang Sendiri: Gratis Minuman.</li><li>Datang Berdua: Minuman + Snack.</li><li>Full Squad: Makan Kenyang!<a href=\"/storage/imports/public/a45c17b93922c3966c09ed460148f08c31a19ee18f0f30f78462e0daa0912249.jpg\"><img src=\"/storage/imports/public/a45c17b93922c3966c09ed460148f08c31a19ee18f0f30f78462e0daa0912249.jpg\" width=\"1080\" height=\"1350\" alt=\"310yRx429Wc4SMUvW0u8kCBTolSosVHGM0tFcTlm.jpg\">Promo</a></li></ul></li></ul>\r\n                ', 'Lomba', 'Tim WadahNgopi', 'imports/public/86520bdd501e8b653ae410a48a613cd17d05f28c3c92e17acd01cb7f9f314ce0.jpg', 'https://wadahngopi.com/information/wn-x-pubg-mobile-mabar-bukber-di-jawara-basecamp-samarinda', 1, '2026-02-22 16:00:00', 27, '2026-10-27 05:52:03', '2026-10-27 07:49:47', NULL),
(11, 'WN x ACRIVOX PUBG Mobile Offline Tournament: Kompetisi Bergengsi Season 1!', 'tournament-pubg-offline-wn-acrivox-samarinda', 'Wadah Nangkring (WN) berkolaborasi dengan Acrivox menggelar turnamen offline PUBG Mobile Season 1. Pendaftaran GRATIS, slot terbatas hanya untuk 32 tim, dan total hadiah Rp 4.000.000', '\r\n                    <p><strong>Wadah Nangkring (WN)</strong> bersama <strong>Acrivox</strong> menghadirkan turnamen PUBG Mobile offline sebagai wadah kompetisi bagi tim terbaik untuk menunjukkan kemampuan dan strategi secara langsung.</p>\r\n\r\n<p>Ini adalah kesempatan bagi komunitas e-sports Samarinda untuk bertanding dalam suasana kompetitif yang profesional.</p>\r\n\r\n<p><strong>Detail Turnamen:</strong></p>\r\n\r\n<ul><li><strong>Main Event:</strong> 28 Februari – 1 Maret 2026</li><li><strong>Prize Pool:</strong> Rp 4.000.000</li><li><strong>Venue:</strong> Wadah Nangkring, Jl. Anggur, Kota Samarinda</li><li><strong>Pendaftaran:</strong> <strong>GRATIS</strong> (Maksimal 32 Tim)</li></ul>\r\n\r\n<p><em>Syarat &amp; Ketentuan berlaku.</em></p>\r\n\r\n<p><strong>Informasi &amp; Registrasi:</strong></p>\r\n\r\n<ul><li><strong>WhatsApp:</strong> 0822-5344-4192</li><li><strong>Instagram:</strong> @wadahnangkring / @acrivox.id</li></ul>\r\n\r\n<p><strong>⚠️ Kuota terbatas.</strong> Segera daftarkan tim Anda sebelum pendaftaran ditutup!</p>\r\n\r\n<p><a href=\"/storage/imports/public/f3c02b188a0bbe8d934b8bfd0dbd7b85ae7cc16064e1dbb6e36f73f0dc9af443.jpg\"><img src=\"/storage/imports/public/f3c02b188a0bbe8d934b8bfd0dbd7b85ae7cc16064e1dbb6e36f73f0dc9af443.jpg\" width=\"1080\" height=\"1350\" alt=\"92Ln8BL4Obq4Cj9ahxYCEuGtsuJGr5QRPRk0k6Lz.jpg\"></a><a href=\"/storage/imports/public/f3c02b188a0bbe8d934b8bfd0dbd7b85ae7cc16064e1dbb6e36f73f0dc9af443.jpg\"><span style=\"text-decoration:underline;\">Lomba</span></a></p>\r\n                ', 'Lomba', 'Tim WadahNgopi', 'imports/public/6da4bfe4ae37099851d1c2cd180afe1366d29cd85746ca473ec318b3c6ed338c.jpg', 'https://wadahngopi.com/information/tournament-pubg-offline-wn-acrivox-samarinda', 1, '2026-02-22 16:00:00', 27, '2026-10-27 05:52:03', '2026-10-27 07:49:47', NULL),
(12, 'Bukber Estetik di Wadah Nangkring (WN): Paket Iftar Mulai 55K Saja!', 'paket-ramadhan-iftar-wadah-nangkring-samarinda', 'Temukan kehangatan Ramadan di Wadah Nangkring (WN). Nikmati paket Iftar personal (55K) atau berdua (110K) dengan pilihan main course populer dan bebas pilih minuman!', '\r\n                    <p>Malam-malam Ramadan memang paling pas dibagikan bersama. Ramadan adalah musim untuk melambatkan langkah, berkumpul, dan menemukan kehangatan dalam momen-momen sederhana.</p>\r\n\r\n<p><strong>Wadah Nangkring (WN)</strong> kini hadir menemani waktu berbuka Anda dengan <strong>Ramadhan Iftar Package</strong> yang disiapkan spesial untuk momen kebersamaan:</p>\r\n\r\n<p><strong>1. Paket 1 Pax (55K)</strong></p>\r\n\r\n<ul><li>1 Main Course</li><li>1 Beverages (Bebas pilih semua varian minuman)</li></ul>\r\n\r\n<p><strong>2. Paket 2 Pax (110K)</strong></p>\r\n\r\n<ul><li>2 Main Course</li><li>2 Beverages (Bebas pilih semua varian minuman)</li></ul>\r\n\r\n<p><strong>Pilihan Main Course (Menu Utama):</strong></p>\r\n\r\n<ul><li>Nasi Goreng</li><li>Salted Egg Chicken</li><li>Chicken Rice Bowl Teriyaki</li><li>Chicken Rice Bowl Lada Hitam</li></ul>\r\n\r\n<p>Segera atur jadwal kumpul Anda dan reservasi tempat sekarang sebelum penuh!</p>\r\n\r\n<p><strong>Lokasi &amp; Reservasi:</strong></p>\r\n\r\n<ul><li><strong>Alamat:</strong> Jl. Anggur, Sidodadi, Samarinda.</li><li><strong>WhatsApp:</strong> 0822-2098-4174</li><li><strong>Instagram:</strong> @wadahnangkring</li></ul>\r\n\r\n<div><a href=\"/storage/imports/public/bbf156e1f1e5810d9663d53b8bc2eef4c304b314d7b9d66b4c72f79e99d547a6.jpg\"><img src=\"/storage/imports/public/bbf156e1f1e5810d9663d53b8bc2eef4c304b314d7b9d66b4c72f79e99d547a6.jpg\" width=\"1024\" height=\"1365\" alt=\"rl7VC7eMg9sirriyykBoKUEYZujKZEAjzoXyLrjV.jpg\">Promo</a><a href=\"/storage/imports/public/aa23a1edc30a08fd5bb38f85284dc8fa2bcadac9d05b3e40479f74e3d52b21f7.jpg\"><img src=\"/storage/imports/public/aa23a1edc30a08fd5bb38f85284dc8fa2bcadac9d05b3e40479f74e3d52b21f7.jpg\" width=\"1024\" height=\"1365\" alt=\"MVNMQDfYDVF9gsOmE5zjvqUAUhYjed2OVIvSL5mt.jpg\">Promo</a></div>\r\n                ', 'Promo', 'Tim WadahNgopi', 'imports/public/251499acfe429167fb3b004369eb2ddefd893a308f205a69abd00e94c6492386.jpg', 'https://wadahngopi.com/information/paket-ramadhan-iftar-wadah-nangkring-samarinda', 1, '2026-02-22 16:00:00', 24, '2026-10-27 05:52:03', '2026-10-27 07:49:47', NULL),
(13, 'Bukber \"Homie\" di VOORVO: Paket Ayam Spesial Mulai 50K & Free Takjil!', 'bukber-homie-di-voorvo-paket-ayam-spesial-mulai-50k-free-takjil', 'Buka puasa makin nikmat bareng orang tersayang di VOORVO food & drink. Dapatkan paket ayam pilihan lengkap dengan minuman mulai 50K dan bonus takjil gratis!', '\r\n                    <p>Buka puasa makin nikmat dan hangat bareng orang tersayang di <strong>VOORVO food &amp; drink</strong>. Dengan suasana yang nyaman dan porsi yang memuaskan, kami hadir dengan <strong>Spesial Ramadhan Menu</strong> yang ramah di kantong.</p>\r\n\r\n<p>Pilih paket favoritmu untuk menemani waktu berbuka:</p>\r\n\r\n<ul><li><strong>Paket 50K (Hemat, Praktis &amp; Lezat)</strong>: Termasuk Nasi Putih, Ayam Pilihan, Ice/Hot Tea, dan <strong>Free Takjil</strong>.</li><li><strong>Paket 55K (Lebih Special &amp; Premium)</strong>: Termasuk Nasi Putih, Ayam Pilihan, <strong>Coffee Series</strong>, dan <strong>Free Takjil</strong>.</li></ul>\r\n\r\n<p><strong>Pilihan Olahan Ayam (Bebas Pilih Rasa)</strong>:</p>\r\n\r\n<ul><li>Telur Asin</li><li>Lada Hitam</li><li>Caramel</li><li>Sambal Matah</li><li>Geprek</li></ul>\r\n\r\n<p>Semua menu kami menggunakan bahan yang <em>fresh</em> dan dijamin halal. Tersedia untuk layanan <em>Dine In</em> maupun <em>Take Away</em>. Pastikan momen Anda lebih istimewa dengan melakukan reservasi sebelum kuota penuh!</p>\r\n\r\n<p><strong>Lokasi &amp; Reservasi</strong>:</p>\r\n\r\n<ul><li><strong>Alamat</strong>: Jl. Durian No. 2, Samarinda.</li><li><strong>WhatsApp</strong>: 0851-8954-6067 atau 0851-7321-8220.</li><li><strong>Instagram</strong>: @voorvo.foodrink.</li></ul>\r\n\r\n<div><a href=\"/storage/imports/public/2c35a2ff6f6bcdb584baaebf3da59fd01d84513d0a90ef15d716ae47d858d855.jpg\"><img src=\"/storage/imports/public/2c35a2ff6f6bcdb584baaebf3da59fd01d84513d0a90ef15d716ae47d858d855.jpg\" width=\"1080\" height=\"1919\" alt=\"GCNO1L2Jj7VvnUEmhucGbZZWyCM7gAjonjAbzQg5.jpg\">Promo</a><a href=\"/storage/imports/public/573bcc9698340e50b9e073c1634e47e0cddf389ce00dd873669c7c7a1a026da5.jpg\"><img src=\"/storage/imports/public/573bcc9698340e50b9e073c1634e47e0cddf389ce00dd873669c7c7a1a026da5.jpg\" width=\"1080\" height=\"1919\" alt=\"q7Kf6p0DyiVpN4Az7ZJnxc7fJ7VJSs9QljXGtWR6.jpg\">Promo</a></div>\r\n                ', 'Promo', 'Tim WadahNgopi', 'imports/public/d23a4933e5b1fcb2fba571f942db405b1e09246a0ede1cc1f1f014a8d613bc93.jpg', 'https://wadahngopi.com/information/bukber-homie-di-voorvo-paket-ayam-spesial-mulai-50k-free-takjil', 1, '2026-02-22 16:00:00', 8, '2026-10-27 05:52:03', '2026-10-27 07:49:47', NULL),
(14, 'Promo Bukber Hemat UNICO Coffee & Cake: Paket Lengkap Mulai 80K untuk Berdua!', 'promo-bukber-unico-coffee-cake-samarinda', 'Ramadan makin manis di UNICO Coffee & Cake! Nikmati paket bukber hemat mulai 80K untuk berdua, lengkap dengan nasi, es teh, dan brownies chocochips andalan UNICO. Cek pilihan paketnya di sini!', '\r\n                    <p>Ramadan semakin dekat! Jadikan momen ini waktu terbaik untuk berkumpul, bercerita, dan berbagi tawa bareng orang tersayang. <strong>UNICO Coffee &amp; Cake</strong> hadir dengan Promo Bukber Spesial yang pastinya ramah di kantong tapi tetap berkelas.</p>\r\n\r\n<p>Berikut pilihan paket yang bisa kamu pilih untuk buka bersama:</p>\r\n\r\n<ul><li><strong>Paket Berdua (Rp80.000)</strong>:<ul><li>2 Porsi Nasi Goreng / Ayam Geprek.</li><li>2 Brownies Chocochips.</li><li>2 Sweet Ice Tea.</li></ul></li><li><strong>Paket Bertiga (Rp115.000)</strong>:<ul><li>3 Porsi Nasi Goreng / Ayam Geprek.</li><li>3 Brownies Chocochips.</li><li>3 Sweet Ice Tea.</li></ul></li><li><strong>Paket Berempat (Rp170.000)</strong>:<ul><li>4 Porsi Nasi Goreng / Ayam Geprek.</li><li>4 Brownies Chocochips.</li><li>4 Sweet Ice Tea + 1 Kentang Goreng.</li></ul></li></ul>\r\n\r\n<p>Menu lengkap, harga hemat, dan suasana yang hangat. Cocok banget buat bukber bareng sahabat, keluarga, sampai rekan kerja di Unico.</p>\r\n\r\n<p><strong>Lokasi &amp; Reservasi:</strong></p>\r\n\r\n<ul><li><strong>Alamat:</strong> Jl. Ir. H. Juanda No. 80C, Samarinda, Kalimantan Timur.</li><li><strong>WhatsApp Reservasi:</strong> +62 857 5313 4298.<a href=\"/storage/imports/public/79b7ef3f6e29c6e4e08279b8138c5567b7e67d5f924cea1cd006d44a34a3957e.jpg\"><img src=\"/storage/imports/public/79b7ef3f6e29c6e4e08279b8138c5567b7e67d5f924cea1cd006d44a34a3957e.jpg\" width=\"1080\" height=\"1350\" alt=\"iWZo5ltRss5S0C35QktSYMpZZGaCm8emwNPrB6Sv.jpg\"></a><a href=\"/storage/imports/public/79b7ef3f6e29c6e4e08279b8138c5567b7e67d5f924cea1cd006d44a34a3957e.jpg\"><span style=\"text-decoration:underline;\">Promo</span></a></li></ul>\r\n                ', 'Promo', 'Tim WadahNgopi', 'imports/public/17a6765df8881c9556980db8032e34b8140914dff263a5b85f3866aaed5177fa.jpg', 'https://wadahngopi.com/information/promo-bukber-unico-coffee-cake-samarinda', 1, '2026-02-22 16:00:00', 12, '2026-10-27 05:52:03', '2026-10-27 07:49:47', NULL),
(15, 'Ramadhan Spesial Menu Kena Samarinda: Rice Bowl Hemat Mulai 35K Free Ice Tea & Kurma!', 'promo-ramadhan-kena-samarinda-kopi', 'Bukber praktis dan nikmat di Kena Kopi & Tea! Nikmati varian Rice Bowl mulai dari 35K, sudah dapat gratis Es Teh dan Kurma. Cek pilihan menunya di sini!', '\r\n                    <p>Ramadhan kali ini jadi lebih spesial di <strong>Kena Samarinda (Kena Kopi &amp; Tea)</strong>. Buat kalian yang cari menu buka puasa yang praktis, mengenyangkan, tapi tetap ramah di kantong, kami menghadirkan <strong>Ramadhan Spesial Menu</strong> dengan harga yang sangat kompetitif.</p>\r\n\r\n<p>Setiap pembelian paket Rice Bowl di bawah ini, kalian sudah otomatis mendapatkan <strong>Free Ice Tea</strong> dan <strong>Kurma</strong> untuk membatalkan puasa.</p>\r\n\r\n<p><strong>Pilihan Ramadhan Spesial Menu:</strong></p>\r\n\r\n<ul><li><strong>Rice Bowl Black Pepper:</strong> 35K</li><li><strong>Rice Bowl Nashville:</strong> 35K</li><li><strong>Rice Bowl Salted Egg:</strong> 40K</li><li><strong>Rice Bowl Beef Belly:</strong> 43K</li></ul>\r\n\r\n<p><strong>Benefit Tambahan:</strong></p>\r\n\r\n<ul><li><strong>FREE Ice Tea:</strong> Langsung dapat es teh manis segar untuk setiap porsi.</li><li><strong>FREE Kurma:</strong> Pembuka puasa sunnah yang manis secara cuma-cuma.</li></ul>\r\n\r\n<p>Jangan sampai kehabisan tempat untuk momen bukber kalian! Segera hubungi nomor reservasi kami agar cerita buka puasa kalian jadi lebih berkesan.</p>\r\n\r\n<p><strong>Reservasi &amp; Informasi:</strong> </p>\r\n\r\n<p><strong>WhatsApp:</strong> 0877-7834-4868</p>\r\n\r\n<p><strong>Instagram: </strong>@kena_samarinda</p>\r\n\r\n<p><a href=\"/storage/imports/public/51e253d31718756072b764bd4629787d6e28bdc4f5050184481a70a54e98a01c.jpg\"><img src=\"/storage/imports/public/51e253d31718756072b764bd4629787d6e28bdc4f5050184481a70a54e98a01c.jpg\" width=\"1080\" height=\"1439\" alt=\"UcAmZW7e98QYLOJswRoeS01jjwALivMUiHUE3dPn.jpg\"></a><a href=\"/storage/imports/public/51e253d31718756072b764bd4629787d6e28bdc4f5050184481a70a54e98a01c.jpg\"><span style=\"text-decoration:underline;\">Promo</span></a></p>\r\n                ', 'Promo', 'Tim WadahNgopi', 'imports/public/a10fc1e73c54cf252ed87afd7f9dcd4e9d9d9e03f4c85cc3c72f15855715e1a1.jpg', 'https://wadahngopi.com/information/promo-ramadhan-kena-samarinda-kopi', 1, '2026-02-21 16:00:00', 22, '2026-10-27 05:52:04', '2026-10-27 07:49:47', NULL),
(16, 'Ramadhan Deals Pluto House: Paket Buka Puasa Hemat Mulai 60K (Free Takjil & Refill Ice Tea)', 'promo-ramadhan-deals-pluto-house', 'Sambut bulan suci dengan paket spesial Ramadhan Deals di Pluto House. Nikmati pilihan Main Course lezat dengan bonus kurama, takjil, dan refill Ice Tea gratis. Cocok untuk buka bersama teman atau keluarga!', '\r\n                    <p>Bulan Ramadhan telah tiba, dan <strong>Pluto House</strong> menghadirkan penawaran spesial <strong>\"Ramadhan Deals\"</strong> untuk menemani momen berbuka puasa Anda. Dengan suasana kedai yang asri dan tenang, kami menyediakan paket makan lengkap yang dirancang khusus untuk kenyamanan Anda berbuka sendiri maupun bersama-sama.</p>\r\n\r\n<p><strong>Pilihan Paket Ramadhan Deals:</strong></p>\r\n\r\n<ol><li>Paket 1 Pax (60K): 1 Main Course + 1 Beverage</li><li>Paket 2 Pax (115K): 2 Main Course + 2 Beverages</li><li>Paket 4 Pax (225K): 4 Main Course + 4 Beverages</li></ol>\r\n\r\n<p><strong>Pilihan Menu Utama (Main Course):</strong> Anda dapat memilih varian menu andalan kami berikut ini:</p>\r\n\r\n<ol><li>Ayam Sambal Matah</li><li>Beef Belly Blackpepper</li><li>Katsu Curry</li><li>Ricebowl Teriyaki</li><li>Ricebowl ala Thai</li><li>Nasi Goreng</li></ol>\r\n\r\n<p><strong>Keuntungan Tambahan (Gratis):</strong> Setiap pembelian paket di atas, Anda akan mendapatkan:</p>\r\n\r\n<ol><li>Free Kurma &amp; Takjil.</li><li>Free Refill Ice Tea untuk semua menu.</li></ol>\r\n\r\n<p>Segera reservasi meja Anda untuk acara Buka Puasa Bersama (Bukber) agar tidak kehabisan tempat. Pluto House adalah pilihan tepat untuk menikmati hidangan lezat dalam balutan suasana yang hangat.<a href=\"/storage/imports/public/fe07c77658803611cdaefb38d28f0eceab5c9bcd974072d7e5300202a2d9f81d.jpg\"><img src=\"/storage/imports/public/fe07c77658803611cdaefb38d28f0eceab5c9bcd974072d7e5300202a2d9f81d.jpg\" width=\"1179\" height=\"2096\" alt=\"tMJvmKetzGhosGuGn5tXTZEj2m9P0JWc8FZ4X3AC.jpg\">Promo</a></p>\r\n                ', 'Promo', 'Tim WadahNgopi', 'imports/public/680cc68351bd1b8d4a09024cf7eb2dad9864367f976bd545b19284b877710442.jpg', 'https://wadahngopi.com/information/promo-ramadhan-deals-pluto-house', 1, '2026-02-21 16:00:00', 25, '2026-10-27 05:52:04', '2026-10-27 07:49:47', NULL);
